<!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><title>سفارش {{ $row->number }}</title><style>body{font-family:Tahoma;background:#07111f;color:#e9f3fb;padding:30px}.box{background:#0a1b2b;padding:22px;border-radius:14px;margin-bottom:16px}button,input{padding:9px;border-radius:8px;border:1px solid #29465e;background:#10283c;color:#fff}button{background:#1c806e}table{width:100%}td,th{padding:9px;border-bottom:1px solid #20384d}.danger{color:#ffb4b4}</style></head><body><div class="box"><h1>سفارش {{ $row->number }}</h1><p>مشتری: {{ $row->customer_name }}</p><p>وضعیت: <b id="status">{{ $row->status }}</b></p><p>موعد مشتری: {{ $row->requested_delivery_at }}</p><p>موعد تولید: {{ $row->production_due_at??'ثبت نشده' }}</p><table><tr><th>کالا</th><th>مقدار</th><th>موجود</th><th>کسری</th><th>وضعیت قلم</th></tr>@foreach($items as $i)<tr><td>{{ $i->goods_name }}</td><td>{{ $i->quantity }}</td><td>{{ $i->available_quantity }}</td><td>{{ $i->shortage_quantity }}</td><td>{{ $i->fulfillment_status }}</td></tr>@endforeach</table></div><div class="box"><button onclick="refreshOrder()">بررسی مجدد موجودی</button>@if(in_array($row->status,['production_required','awaiting_production']))<form onsubmit="setDue(event)" style="margin-top:12px"><input id="due" type="date" required><button>ثبت موعد قابل تحویل تولید</button></form>@endif@if($row->status==='ready_for_delivery')<form onsubmit="requestDelivery(event)" style="margin-top:12px"><input id="scheduled" type="datetime-local" required><input id="recipient" placeholder="شخص تحویل‌گیرنده" required><input id="vehicle" placeholder="وسیله حمل"><button>ثبت درخواست تحویل</button></form>@endif</div><script>const token='{{ csrf_token() }}';async function call(url,data={}){const r=await fetch(url,{method:'POST',headers:{'Accept':'application/json','Content-Type':'application/json','X-CSRF-TOKEN':token},body:JSON.stringify(data)});const j=await r.json();if(!r.ok)throw Error(j.message||'خطا');return j}async function refreshOrder(){try{const j=await call('{{ route('sales.orders.refresh',$row->id) }}');document.getElementById('status').textContent=j.data.status;location.reload()}catch(e){alert(e.message)}}async function setDue(e){e.preventDefault();try{await call('{{ route('sales.orders.production-due',$row->id) }}',{production_due_at:document.getElementById('due').value});location.reload()}catch(x){alert(x.message)}}async function requestDelivery(e){e.preventDefault();try{await call('{{ route('sales.orders.delivery-request',$row->id) }}',{scheduled_at:document.getElementById('scheduled').value,recipient_name:document.getElementById('recipient').value,vehicle:document.getElementById('vehicle').value});location.reload()}catch(x){alert(x.message)}}</script></body></html>